// (?\t\n\u{c}\r \u{a0}\u{2000}-\u{200b}\u{202f}\u{205f}\u{2060}\u{3000}\u{feff})
func (p *parser) e1() (*Node, bool) {
	ch, size, ok := p.peek()
	if !ok || !(ch == 9 || ch == 10 || ch == 12 || ch == 13 || ch == 32 || ch == 160 || ch >= 8192 && ch <= 8203 || ch == 8239 || ch == 8287 || ch == 8288 || ch == 12288 || ch == 65279) {
		p.expect(p.pos, 5)
		return nil, false
	}
	return p.single(size, true)
}

// (?\t\n\u{c}\r \u{a0}\u{2000}-\u{200b}\u{202f}\u{205f}\u{2060}\u{3000}\u{feff})*
func (p *parser) e2() (*Node, bool) {
	start := p.pos
	base := len(p.kidStack)
	count := 0
	for {
		m0 := p.mark()
		prevCut, prevFrame := p.cut, p.frame
		p.cut = false
		v, ok := p.e1()
		cut := p.cut
		p.cut, p.frame = prevCut, prevFrame
		if !ok {
			p.reset(m0)
			if cut {
				p.dropKids(base)
				return nil, false
			}
			break
		}
		count++
		p.kidStack = append(p.kidStack, v)
		if p.pos == m0.pos && count >= 0 {
			break
		}
	}
	if count < 0 {
		p.dropKids(base)
		return nil, false
	}
	return p.newNode(Node{kind: kindList, Start: int32(start), End: int32(p.pos), Children: p.kids(base), fresh: true}), true
}

